SET local check_function_bodies = off;

DROP POLICY "Allow anon insert transactions" ON "public"."transactions";

DROP POLICY "Allow anon to delete transactions" ON "public"."transactions";

DROP POLICY "Allow anon to read transactions" ON "public"."transactions";

CREATE TABLE "public"."user_roles" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "user_id"    uuid                     DEFAULT gen_random_uuid(),
  CONSTRAINT "user_roles_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."user_roles"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.prevent_user_id_change()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
begin
  if new.user_id is distinct from old.user_id then
    raise exception 'user_id cannot be changed';
  end if;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."prevent_user_id_change"() FROM "anon", "authenticated", "service_role";

ALTER TABLE "public"."user_roles"
  ADD CONSTRAINT "user_roles_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE CASCADE;

CREATE TRIGGER prevent_transaction_user_id_change
  BEFORE UPDATE ON public.transactions
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_user_id_change();

CREATE POLICY "Users can delete their own transactions" ON "public"."transactions"
  FOR DELETE
  TO "authenticated"
  USING ((auth.uid() = user_id));

CREATE POLICY "Users can update their own transactions" ON "public"."transactions"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() = user_id))
  WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can view their own transactions" ON "public"."transactions"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = user_id));

COMMENT ON TABLE "public"."user_roles" IS 'Defines user roles for managing access levels and permissions';

GRANT EXECUTE ON FUNCTION "public"."prevent_user_id_change"() TO PUBLIC, "postgres";

REVOKE ALL ON TABLE "public"."user_roles" FROM "anon";

GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON TABLE "public"."user_roles" TO "anon";

REVOKE ALL ON TABLE "public"."user_roles" FROM "authenticated";

GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON TABLE "public"."user_roles" TO "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."user_roles" TO "postgres";

REVOKE ALL ON TABLE "public"."user_roles" FROM "service_role";

GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON TABLE "public"."user_roles" TO "service_role";

ALTER TABLE "public"."transactions"
  ALTER COLUMN "user_id" SET DEFAULT auth.uid();

